-- 2026-10-12 SPAC price list import - 4702 items from SPAC_PRICE_LIST_LP.xlsx
-- Principal Shree Prayag Air Controls (code SPAC), division Pneumatic, item type Trading, all active branches.
-- Run once in phpMyAdmin (SQL tab or Import) on the bie database. Safe to run again:
-- a sales code already imported under SPAC is skipped, missing categories / HSN are added only once.
--
-- Column mapping
--   Category                         -> category (added to mst_category if missing)
--   Description                      -> item description (upper case)
--   Supplier Item Code               -> supplier item code
--   Sales Item Code & Purchase Code  -> sales item code and purchase code
--   UOM                              -> uom (PCS = NOS, ROLL = ROLLS, #N/A = NOT APPLICABLE)
--   HSN                              -> hsn (added to mst_hsn if missing, #N/A = NA 0%)
--   Item Price & selling price       -> item price and selling price
--   Item Discount                    -> item discount (0.28 = 28%), cost = price less discount, margin from cost to selling
--   SALE DISCOUNT                    -> min / max discount (0-10% = 0 and 10) for every branch
-- Multiple UOM none, no default supplier, stock 0 - same as saving the item form.

SET NAMES utf8mb4;

-- staging copy of the sheet, dropped at the end
DROP TABLE IF EXISTS tmp_spac_import;
CREATE TABLE tmp_spac_import (
  row_no INT NOT NULL PRIMARY KEY,
  category VARCHAR(50) NOT NULL,
  description VARCHAR(250) NOT NULL,
  supp_code VARCHAR(40) NOT NULL,
  item_code VARCHAR(40) NOT NULL,
  uom_name VARCHAR(50) NOT NULL,
  hsn_code VARCHAR(10) NOT NULL,
  price DECIMAL(12,2) NOT NULL,
  discount DECIMAL(6,2) NOT NULL,
  min_discount DECIMAL(12,2) NOT NULL,
  max_discount DECIMAL(12,2) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;












-- sheet names to the names in the masters
UPDATE tmp_spac_import SET uom_name = 'NOS' WHERE uom_name = 'PCS';
UPDATE tmp_spac_import SET uom_name = 'ROLLS' WHERE uom_name = 'ROLL';
UPDATE tmp_spac_import SET uom_name = 'NOT APPLICABLE', hsn_code = 'NA' WHERE uom_name = '#N/A' OR hsn_code = '#N/A';
UPDATE tmp_spac_import SET category = 'FITTINGS' WHERE category = 'FITTING';

SET @principal = (SELECT MIN(principal_id) FROM mst_principal WHERE principal_code = 'SPAC');
SET @division = (SELECT MIN(division_id) FROM mst_division WHERE division_name = 'PNEUMATIC');
SET @branches = (SELECT GROUP_CONCAT(branch_id ORDER BY branch_id) FROM mst_branch WHERE branch_status = 1);

START TRANSACTION;

-- 1. categories not there yet
SELECT 0, x.category, '', 1, 1, NOW(), 1, NOW()
FROM (SELECT DISTINCT category FROM tmp_spac_import) x
WHERE NOT EXISTS (SELECT 1 FROM mst_category c WHERE TRIM(c.category_name) = x.category);

-- 2. hsn codes not there yet - all 18% (9 + 9) per the GST rate schedule from 22-09-2025
SELECT '', x.hsn_code, x.hsn_code, x.igst / 2, x.igst / 2, x.igst, 1
FROM (SELECT '39173290' AS hsn_code, 18 AS igst UNION ALL
      SELECT '39174000', 18 UNION ALL
      SELECT '40169390', 18 UNION ALL
      SELECT '84678910', 18 UNION ALL
      SELECT '84812000', 18 UNION ALL
      SELECT '85045090', 18 UNION ALL
      SELECT '85365090', 18 UNION ALL
      SELECT '85444999', 18) x
WHERE x.hsn_code IN (SELECT hsn_code FROM tmp_spac_import)
  AND NOT EXISTS (SELECT 1 FROM mst_hsn h WHERE h.hsn_code = x.hsn_code);

-- 3. items - skipped if the sales code is already there under SPAC
  item_principal, item_division, item_code, item_purchase_code, supp_item_code, item_category, item_desciption,
  item_uom, multi_uom_id, item_production_sales, item_brand_make, item_model_manufac, item_color,
  item_price, item_discount, item_cost_price, item_selling_price, margin_percent, item_image,
  item_min_qty, item_order_min_qty, item_opening_stock, item_curr_stock, item_allotted_qty, item_remarks,
  item_hsn, item_dept_sales, item_dept_purchase, item_dept_product, item_max_qty, item_status,
  modify_by, modify_date_time, new_item)
SELECT @branches, 1, 2, 0, '', 0,
  @principal, @division, s.item_code, s.item_code, s.supp_code,
  (SELECT MIN(c.category_id) FROM mst_category c WHERE TRIM(c.category_name) = s.category),
  s.description,
  (SELECT MIN(u.uom_id) FROM mst_uom u WHERE u.uom_name = s.uom_name), '', '', 0, '', 0,
  s.price, s.discount, ROUND(s.price - s.price * s.discount / 100, 2), s.price,
  IF(ROUND(s.price - s.price * s.discount / 100, 2) = 0, 0,
     ROUND((s.price - ROUND(s.price - s.price * s.discount / 100, 2)) / ROUND(s.price - s.price * s.discount / 100, 2) * 100, 2)),
  '', 0, 0, 0, 0, 0, '',
  (SELECT MIN(h.hsn_id) FROM mst_hsn h WHERE h.hsn_code = s.hsn_code), 1, 1, 0, 0, 1,
  0, NULL, 0
FROM tmp_spac_import s
WHERE @principal IS NOT NULL AND @division IS NOT NULL AND @branches IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM tbl_item_details d WHERE d.item_code = s.item_code AND d.item_principal = @principal)
ORDER BY s.row_no;

-- 4. stock row per new item - prices, discounts and min / max discount on every branch, stock 0
  ho_stock, ho_loc_row, ho_loc_rack, ho_item_price, ho_item_discount, ho_item_min_discount, ho_item_max_discount,
  ho_item_cost_price, ho_item_selling_price, ho_item_margin, ho_item_min_qty, ho_item_order_min_qty, ho_item_max_qty,
  kl_stock, kl_loc_row, kl_loc_rack, kl_item_price, kl_item_discount, kl_item_min_discount, kl_item_max_discount,
  kl_item_cost_price, kl_item_selling_price, kl_item_margin, kl_item_min_qty, kl_item_order_min_qty, kl_item_max_qty,
  rjpm_stock, rjpm_loc_row, rjpm_loc_rack, rjpm_item_price, rjpm_item_discount, rjpm_item_min_discount, rjpm_item_max_discount,
  rjpm_item_cost_price, rjpm_item_selling_price, rjpm_item_margin, rjpm_item_min_qty, rjpm_item_order_min_qty, rjpm_item_max_qty)
SELECT d.item_id,
  0, 0, 0, d.item_price, d.item_discount, s.min_discount, s.max_discount,
  d.item_cost_price, d.item_selling_price, d.margin_percent, 0, 0, 0,
  0, 0, 0, d.item_price, d.item_discount, s.min_discount, s.max_discount,
  d.item_cost_price, d.item_selling_price, d.margin_percent, 0, 0, 0,
  0, 0, 0, d.item_price, d.item_discount, s.min_discount, s.max_discount,
  d.item_cost_price, d.item_selling_price, d.margin_percent, 0, 0, 0
FROM tbl_item_details d
JOIN tmp_spac_import s ON s.item_code = d.item_code
WHERE d.item_principal = @principal
  AND NOT EXISTS (SELECT 1 FROM tbl_item_stock t WHERE t.item_id = d.item_id)
ORDER BY d.item_id;

COMMIT;

-- 5. checks - first two should be 4702 and 0, the third should be empty
SELECT COUNT(*) AS spac_items_in_sheet_found FROM tbl_item_details d JOIN tmp_spac_import s ON s.item_code = d.item_code WHERE d.item_principal = @principal;
SELECT COUNT(*) AS spac_items_without_stock_row FROM tbl_item_details d JOIN tmp_spac_import s ON s.item_code = d.item_code WHERE d.item_principal = @principal AND NOT EXISTS (SELECT 1 FROM tbl_item_stock t WHERE t.item_id = d.item_id);
SELECT d.item_id, d.item_code, d.item_category, d.item_uom, d.item_hsn FROM tbl_item_details d JOIN tmp_spac_import s ON s.item_code = d.item_code
WHERE d.item_principal = @principal AND (d.item_category = 0 OR d.item_category IS NULL OR d.item_hsn IS NULL OR d.item_uom IS NULL) LIMIT 20;

DROP TABLE IF EXISTS tmp_spac_import;
